private updateFenceFromLine(): void {
  const codeFence = this.currentLineFenceToken();
  if (!codeFence) {
    return;
  }
  if (!this.activeFence) {
    this.openFence(codeFence);
    return;
  }
  if (codeFence.startsWith(this.activeFence)) {
    this.closeFence();
  }
}

private replaceLinksInCurrentLine(): string {
  let modifiedLine = this.scannedLine;
  // Replace inline-style links or reference-style links e.g:
  // This is [Document 1](doc1.md)
  // [doc1]: doc1.md
  const mdRegex =
    /(?:\]\(|\]:\s*)(?!https?:\/\/|@site\/)<?(?<filename>[^'"\]\s>]+(?:\s[^'"\]\s>]+)*\.mdx?)>?/g;
  let mdMatch = mdRegex.exec(modifiedLine);
  while (mdMatch !== null) {
    // Replace it to correct html link.
    const mdLink = mdMatch.groups!.filename!;
    this.collectCandidateRoots(mdLink);

    const aliasedSourceMatch = this.candidateRoots
      .map((p) => path.join(p, decodeURIComponent(mdLink)))
      .map((source) => this.aliasResolvedPath(source))
      .find((source) => this.hasPermalink(source));

    const permalink: string | undefined = aliasedSourceMatch
      ? this.lookupPermalink(aliasedSourceMatch)
      : undefined;

    if (permalink) {
      // MDX won't be happy if the permalink contains a space, we need to
      // convert it to %20
      const encodedPermalink = this.encodePermalinkSpaces(permalink);
      modifiedLine = modifiedLine.replace(
        mdMatch[0]!,
        mdMatch[0]!.replace(mdLink, encodedPermalink),
      );
      // Adjust the lastIndex to avoid passing over the next link if the
      // newly replaced URL is shorter.
      mdRegex.lastIndex += encodedPermalink.length - mdLink.length;
    } else {
      this.recordBrokenLink(mdLink, this.currentFilePosix(), this.currentContentRoots());
    }
    mdMatch = mdRegex.exec(modifiedLine);
  }
  this.captureCurrentLine(modifiedLine);
  return modifiedLine;
}

private collectCandidateRoots(mdLink: string): void {
  this.resetCandidateRoots();
  if (this.shouldSearchContentRoots(mdLink)) {
    this.addContentRootsToCandidates();
    this.addSiteDirToCandidates();
  }
  if (this.shouldSearchFileDir(mdLink)) {
    this.addFileDirToCandidates();
  }
}

private shouldSearchContentRoots(mdLink: string): boolean {
  if (mdLink.startsWith('./')) {
    return false;
  }
  if (mdLink.startsWith('../')) {
    return false;
  }
  return true;
}

private shouldSearchFileDir(mdLink: string): boolean {
  if (mdLink.startsWith('/')) {
    return false;
  }
  return true;

